INSERT INTO public.settings (key, value) VALUES ('temple_timings', '{"morning_puja":"সকাল ৭:০০ - সকাল ৯:৩০","morning_puja_en":"7:00 AM - 9:30 AM","morning_desc":"প্রভাতী নিত্যপূজা, মঙ্গল আরতি ও পুষ্পাঞ্জলি","morning_desc_en":"Morning Puja, Mangal Aarti & Pushpanjali","bhog_time":"দুপুর ১২:০০ - দুপুর ১:৩০","bhog_time_en":"12:00 PM - 1:30 PM","bhog_desc":"মহাপ্রসাদ ও দ্বিপ্রহরিক ভোগ নিবেদন","bhog_desc_en":"Midday Bhog Offering & Sanctum Darshan","sandhya_aarti":"সন্ধ্যা ৬:০০ - রাত ৮:০০","sandhya_aarti_en":"6:00 PM - 8:00 PM","sandhya_desc":"সন্ধ্যা আরতি, ধূপারতি, পদাবলি কীর্তন ও শঙ্খধ্বনি","sandhya_desc_en":"Evening Aarti, Dhoop Aarti, Kirtan & Conch blowing","darshan_note":"প্রতিদিন সাধারণ ভক্ত ও পুণ্যার্থীদের জন্য গর্ভগৃহ দর্শন ও আশীর্বাদ উন্মুক্ত থাকে। বিশেষ তিথিতে সারারাত মায়ের পূজা অনুষ্ঠিত হয়।","darshan_note_en":"Sanctum darshan is open daily for devotees. Special pujas continue through the night on auspicious festivals.","status_override":"auto","special_notice":"আসন্ন শ্রাবণ সংক্রান্তির বাৎসরিক মহোৎসবে দিন-রাত অহোরাত্র পূজা চলবে।"}') ON CONFLICT (key) DO UPDATE SET value = EXCLUDED.value;
INSERT INTO public.settings (key, value) VALUES ('travel_info', '{"dhaka_bus":"ঢাকা (গুলিস্তান / সায়েদাবাদ / গাবতলী) হতে পদ্মা সেতু হয়ে বরিশাল বা গৌরনদীগামী বাসে চড়ে গৌরনদী বা আগৈলঝাড়া বাসস্ট্যান্ডে নামুন। সেখান থেকে স্থানীয় ইজিবাইক বা অটোরিকশায় মাত্র ৫-১০ মিনিটে পৌঁছে যাবেন ঐতিহাসিক গৈলা মা মনসা মন্দিরে।","dhaka_bus_en":"From Dhaka (Gulistan / Sayedabad / Gabtoli), take any Barishal/Gournadi bound bus via Padma Bridge. Drop off at Gournadi or Agailjhara bus stand, then take an auto-rickshaw (5-10 minutes) directly to Goila Manasa Temple.","launch_route":"ঢাকা সদরঘাট হতে বিলাসবহুল লঞ্চে বরিশাল নদীবন্দর। সেখান থেকে নথুল্লাবাদ টার্মিনাল হয়ে গৌরনদী/আগৈলঝাড়া এবং সরাসরি গৈলা বাজার।","launch_route_en":"Take a passenger launch from Dhaka Sadarghat to Barishal River Port, then from Nathullabad Bus Terminal take a local bus to Gournadi/Agailjhara and arrive at Goila Bazar.","local_transport":"আগৈলঝাড়া উপজেলা সদর থেকে ৩ কিমি পূর্বে এবং গৌরনদী পৌরসভা থেকে ৫ কিমি পশ্চিমে মন্দিরটি অবস্থিত। স্থানীয় অটোরিকশা, মাহিন্দ্রা ও ভ্যান সার্বক্ষণিক চলাচল করে।","local_transport_en":"Located 3 km east of Agailjhara upazila and 5 km west of Gournadi municipality. Easy auto-rickshaws and vans are available round-the-clock.","helpline_phone":"01717503657","priest_phone":"01735737308","guest_house":"মন্দির চত্বরে দূর-দূরান্তের ভক্তদের বিশ্রাম ও পানীয় জলের সুন্দর সুব্যবস্থা রয়েছে। দূরবর্তী পুণ্যার্থীদের জন্য গৌরনদী ও বরিশালে সুসজ্জিত আবাসিক হোটেল ও সরকারি ডাকবাংলো রয়েছে।","guest_house_en":"Rest areas and drinking water are available inside temple premises. For overnight stays, standard residential hotels and rest houses are nearby in Gournadi and Barishal town.","map_link":"https://maps.google.com/?q=22.9555,90.2215"}') ON CONFLICT (key) DO UPDATE SET value = EXCLUDED.value;
INSERT INTO public.settings (key, value) VALUES ('sacred_mantras', '[{"id":1,"title":"মা মনসার প্রণাম মন্ত্র","title_en":"Devi Manasa Pranam Mantra","sanskrit":"ওঁ আস্তীকস্য মুনের্মাতা ভগিনী বাসুকেস্তথা ।\nজরৎকারুমুনেঃ পত্নী মনসাদেবী নমোহস্তুতে ॥","pronunciation":"ওঁ আস্তীকস্য মুনের্মাতা ভগিনী বাসুকেস্তথা। জরৎকারুমুনেঃ পত্নী মনসাদেবী নমোহস্তুতে॥","meaning":"হে মুনি আস্তীকের জননী, নাগরাজ বাসুকির ভগিনী এবং তপস্বী জরৎকারু মুনির পরম ধার্মিক পত্নী দেবি মনসা, আপনাকে আমার ভক্তিপূর্ণ শতকোটি প্রণাম।","meaning_en":"O Mother of sage Astika, sister of serpent king Vasuki, and devoted consort of sage Jaratkaru, salutations unto Goddess Manasa.","category":"প্রণাম","category_en":"Pranam"},{"id":2,"title":"মা মনসার ধ্যান মন্ত্র","title_en":"Devi Manasa Dhyana Mantra","sanskrit":"ওঁ হেমগৌরাং রত্নভূষাং শুভ্রবস্ত্রাবৃতাং সতীম্ ।\nকোটিচন্দ্রপ্রভাং দেবীং নাগযজ্ঞোপবীতিনীম্ ॥","pronunciation":"ওঁ হেমগৌরাং রত্নভূষাং শুভ্রবস্ত্রাবৃতাং সতীম্। কোটিচন্দ্রপ্রভাং দেবীং নাগযজ্ঞোপবীতিনীম্॥","meaning":"স্বর্ণকান্তিযুক্তা, বহুমূল্য রত্নালঙ্কারে সজ্জিতা, শুভ্র বসনা, কোটি চন্দ্রের জ্যোতিসম্পন্না এবং পবিত্র নাগ-যজ্ঞোপবীতধারিণী শ্রী শ্রী মা মনসাকে আমি অন্তরে ধ্যান করি।","meaning_en":"I meditate upon Goddess Manasa, whose complexion is like molten gold, adorned with celestial jewels, clad in pure white, luminous like millions of moons, and wearing a sacred serpent sacred thread.","category":"ধ্যান","category_en":"Dhyana"},{"id":3,"title":"কবি বিজয় গুপ্তের অমর পদ্মপুরাণ পদাবলি","title_en":"Immortal Verse from Padma Purana by Poet Bijoy Gupta","sanskrit":"গৈলা নামে গ্রামখানি সর্বগুণে ধান্দা ।\nতাহাতে বসতি করে লোক পঞ্চনন্দা ॥\nপশ্চিমে পশ্চিমে নদী মধ্যে ফুল্লশ্রী ।\nতাহাতে বিজয় গুপ্ত রচে দেবীর চরিত্রী ॥","pronunciation":"গৈলা নামে গ্রামখানি সর্বগুণে ধান্দা। তাহাতে বসতি করে লোক পঞ্চনন্দা। পশ্চিমে পশ্চিমে নদী মধ্যে ফুল্লশ্রী। তাহাতে বিজয় গুপ্ত রচে দেবীর চরিত্রী॥","meaning":"মহাকবি বিজয় গুপ্ত তাঁর অমর পদ্মাপুরাণ (মনসামঙ্গল) কাব্যের সূচনায় নিজ জন্মভূমি পুণ্যতোয়া গৈলা (তৎকালীন ফুল্লশ্রী) গ্রামের অনুপম প্রাকৃতিক রূপ ও দেবী মনসার মহিমা কীর্তন করেছেন।","meaning_en":"Poet Bijoy Gupta recorded the beauty and spiritual legacy of his birthplace Goila (historic Phullashri) as he commenced composing the epic Padma Purana by divine decree.","category":"পদ্মপুরাণ","category_en":"Padma Purana"},{"id":4,"title":"আস্তীক মুনির নাগভয় নিবারক মন্ত্র","title_en":"Sage Astika Fear-dispelling Mantra","sanskrit":"সর্পাপসর্প ভদ্রং তে গচ্ছ সর্প মহাবিষ ।\nজনমেজয়স্য যজ্ঞানান্তে আস্তীকবচনং স্মর ॥","pronunciation":"সর্পাপসর্প ভদ্রং তে গচ্ছ সর্প মহাবিষ। জনমেজয়স্য যজ্ঞানান্তে আস্তীকবচনং স্মর॥","meaning":"হে বিষধর সর্পগণ, তোমাদের কল্যাণ হোক, তোমরা নির্বিঘ্নে প্রস্থান করো। রাজা জনমেজয়ের সর্পযজ্ঞ অবসানে মহর্ষি আস্তীকের পবিত্র সত্যবচন স্মরণ করো। ভক্তদের বিশ্বাস, এই শ্লোক স্মরণে সর্বপ্রকার ভয় ও বিঘ্ন দূরীভূত হয়।","meaning_en":"Depart, O serpents, may peace be upon you. Remember the sacred vow of Sage Astika at the conclusion of King Janamejaya''s sacrifice.","category":"রক্ষা মন্ত্র","category_en":"Protection"}]') ON CONFLICT (key) DO UPDATE SET value = EXCLUDED.value;

