INSERT INTO public.testimonials (id, date, name, designation, text) VALUES (4, '2024-02-16', 'মোঃ দেলোয়ার হোসেন', 'অতিরিক্তি পরিচালক, বাংলাদেশ ব্যাংক', 'দেবীর সকল ভক্তদের মঙ্গল কামনা করছি। দেবীর আশির্বাদে জগতের সকলের মঙ্গল সাধিত হোক।
') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.testimonials (id, date, name, designation, text) VALUES (5, '2023-12-20', 'রুম্পা সিকদার', 'অতিরিক্ত জেলা প্রশাসক (শিক্ষা ও আইসিটি) বরিশাল', 'আজ সোমবার বিকাল ৪.৩০ মিনিটে মনসা মন্দির পরিদর্শন করার সৌভাগ্য হয়। এখানে এসিল্যান্ড বার্নীন সহ অন্যান্য গন্যমান্য ব্যক্তিবর্গ উপস্থিত ছিলেন। কবি বিজয় গুপ্ত প্রতিষ্ঠিত মনসা মন্দির সম্পর্কে অনেক তথ্য শুনে সমৃদ্ধ হলাম। সবার মঙ্গল কামনা করছি।
') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.testimonials (id, date, name, designation, text) VALUES (6, '2024-01-26', 'প্রফেসর ডা. অমর কুমার সাহা', 'সাতক্ষীরা মেডিকেল কলেজ', 'সনাতন ধর্ম ও ধর্মীয় স্থাপনা ও মন্দিরের সংরক্ষন ও মর্যাদা রক্ষা করা সব সনাতনীর নৈতিক ও সামাজিক দায়িত্ব। একটি সুসংঘটিত প্রতিষ্ঠান পরিদর্শন করতে পেরে আনন্দিত।
') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.testimonials (id, date, name, designation, text) VALUES (7, '', 'মোহাম্মদ বেলায়েত হোসেন', 'পুলিশ সুপার, বরিশাল', 'ঐতিহাসিক এই মন্দির পরিদর্শন আমার জন্য এক গার্বের বিষয়।
আমার আবার পরিদর্শনের ইচ্ছা রইল।

') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.testimonials (id, date, name, designation, text) VALUES (8, '2024-12-20', 'তানভীর নাহিদ খান', 'সহকারী অধ্যাপক, থিয়েটার এবং পারফারমেন্স স্টাডিজ বিভাগ, ঢাক বিশ্ববিদ্যালয়', 'কবি বিজয়গুপ্তের পূণ্য জন্মাভূমি ও মনসামন্দির দর্শন করে ভীষণ আনন্দিত। মনসামন্দিরে পদ্মা পুরাণের পরিবেশনা ,দেশজ নাট্য রয়ানী দেখা চমৎকার অভিষ্কতা। পূণ্যভূমি অটুট থাকুক, মনসামন্দির স্বমহিমায় টিঁকে থাকুক, রয়ানী পরিবেশিত হোক অনন্ত কাল ধরে। জয়তু দেশজ নাট্য ,জয়তু রয়ানী, জয়তু বাংলা সংস্কৃতি বৈচিত্রের ভেতর ঐক্য প্রতিষ্ঠিত হোক বাংলাদেশে।
') ON CONFLICT (id) DO NOTHING;
