-- 6. Populate Events (6 items)
INSERT INTO public.events (id, title, date, description, image) VALUES (4, 'সাপ্তাহিক খিচুড়ি প্রসাদ বিতরণ কার্যক্রম চলমান', '2026-03-22', 'প্রতি রবিবারের ন্যায় আজও শ্রী শ্রী মা মনসা মন্দিরে ভক্তবৃন্দের মাঝে সাপ্তাহিক খিচুড়ি প্রসাদ বিতরণ করা হয়েছে।
মায়ের কৃপায় আজকের এই প্রসাদ বিতরণ কার্যক্রম শান্তিপূর্ণ ও সুশৃঙ্খলভাবে সম্পন্ন হয় এবং আজ মায়ের ভক্তবৃন্দদের উপস্থিতি ছিলো চোখে পরার মতো।

প্রসাদ বিতরণে অনুদান অথবা সহযোগিতা করতে আগ্রহীরা আমাদের নির্বাহী কমিটির সঙ্গে যোগাযোগ করতে অনুরোধ করা হলো।

মা মনসার কৃপা সকলের ওপর বর্ষিত হোক।

আয়োজনে: কবি বিজয় গুপ্তের স্মৃতি রক্ষা, শ্রী শ্রী মা মনসা মন্দির সংরক্ষণ ও উন্নয়ন কমিটি।', 'images/events/event_4.jpg') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.events (id, title, date, description, image) VALUES (2, 'নব-নির্বাচিত মাননীয় সংসদ সদস্য এবং তথ্য ও সম্প্রচার মন্ত্রী জননেতা এম. জাহির উদ্দিন স্বপন মহোদয় শুভেচ্ছা।', '2026-02-22', 'ত্রয়োদশ জাতীয় সংসদ জাতীয় সংসদ নির্বাচনে বরিশাল-১ আসনে জনগণের আশীর্বাদ ও ভালোবাসায় বিপুল ভোটে নব-নির্বাচিত মাননীয় সংসদ সদস্য, অসাম্প্রদায়িক চেতনার অহংকার জননেতা এম. জাহির উদ্দিন স্বপন মহোদয়ের
ঐতিহাসিক বিজয় এবং তথ্য ও সম্প্রচার মন্ত্রীর দায়িত্ব প্রাপ্তিতে জানাই আন্তরিক অভিনন্দন ও শুভেচ্ছা।
মহান দায়িত্ব পালনে আপনার নেতৃত্বে দেশ ও জনগণ উপকৃত হোক এই কামনা করি।
কবি বিজয় গুপ্তের স্মৃতিরক্ষা, শ্রীশ্রী মা-মনসা মন্দির সংরক্ষণ ও উন্নয়ন কমিটি', 'images/events/event_2.jpg') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.events (id, title, date, description, image) VALUES (3, 'মনসা মন্দির আঙিনায় বড়ঠাকুর এর মন্দির এর ছাদ ঢালাই', '2026-03-20', 'মনসা মন্দির আঙিনায় বড়ঠাকুর এর মন্দির এর ছাদ ঢালাই হলো। আপনি যদি এ মহৎ কাজে অংশীদার হতে আগ্রহী হন তবে নিজ আগ্রহে যোগাযোগ করুন। সকলের উপর বড়ঠাকুরের আশীর্বাদ বর্ষিত হোক।

কবি বিজয় গুপ্তের স্মৃতিরক্ষা, শ্রীশ্রী মা-মনসা মন্দির সংরক্ষণ ও উন্নয়ন কমিটি
', 'images/events/event_3.jpg') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.events (id, title, date, description, image) VALUES (1, 'দেশনেত্রী ও প্রাক্তন প্রধানমন্ত্রী বেগম খালেদা জিয়া’র বিদেহী আত্মার চিরশান্তি কামনায় বিশেষ প্রার্থনা ', '2026-01-04', 'আজ মন্দির প্রাঙ্গণে প্রয়াত দেশনেত্রী ও প্রাক্তন প্রধানমন্ত্রী বেগম খালেদা জিয়া’র বিদেহী আত্মার চিরশান্তি কামনায় বিশেষ প্রার্থনা অনুষ্ঠিত হয়।
এই আয়োজনে তাঁর আত্মার সদ্গতি ও পরলোকগমনে চিরশান্তি কামনা করা হয়। 
সার্বিক তত্ত্বাবধানে ও আয়োজনে:
কবি বিজয় গুপ্তের স্মৃতি রক্ষা, শ্রী শ্রী মা মনসা মন্দির সংরক্ষণ ও উন্নয়ন কমিটি', 'images/events/event_1.jpg') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.events (id, title, date, description, image) VALUES (5, 'কার্যকারী কমিটির সদস্যবৃন্দের উপস্থিতিতে একটি জরুরি সভা অনুষ্ঠিত', '2026-03-22', 'আজ ২২/০৩/২০২৬ তারিখে কার্যকারী কমিটির সদস্যবৃন্দের উপস্থিতিতে একটি জরুরি সভা অনুষ্ঠিত হয়। সভায় মন্দিরের উন্নয়ন, চলমান কার্যক্রম সমূহ, আসন্ন পহেলা বৈশাখ উদযাপনসহ বিভিন্ন গুরুত্বপূর্ণ বিষয়ে আলোচনা ও সিদ্ধান্ত গৃহীত হয়।

উপস্থিত সকল সদস্যবৃন্দকে আন্তরিক ধন্যবাদ জানানো হলো।

মা মনসার কৃপায় সবার মঙ্গল সাধন হোক।
জয় মা মনসা।

কবি বিজয় গুপ্তের স্মৃতি রক্ষা,
শ্রী শ্রী মা মনসা মন্দির সংরক্ষণ ও উন্নয়ন কমিটি', 'images/events/event_5.jpg') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.events (id, title, date, description, image) VALUES (7, 'গৈলার ঐতিহ্যবাহী শ্রীশ্রী মা মনসা মন্দিরের বাৎসরিক পূজা সফলভাবে উদযাপিত হয়েছে', '2026-08-19', '<p>কবি বিজয় গুপ্তের স্মৃতি রক্ষা ও মা মনসা মন্দির সংরক্ষণ ও উন্নয়ন কমিটি-এর উদ্যোগে আয়োজিত এই পবিত্র উৎসবে বিগত বছরগুলোর তুলনায় এ বছর <strong>রেকর্ড সংখ্যক সর্বোচ্চ ভক্তের সমাগম ঘটেছে</strong>। মন্দির প্রাঙ্গণ ছিল কানায় কানায় পূর্ণ।</p><p>ডিজিটাল প্লাটফর্ম গুলোতেও ব্যাপক প্রচার প্রচারণা হয়েছে। অসংখ্য গণমাধ্যমে খবর হয়েছে। হাজার হাজার ভক্ত মায়ের চরণে পূজা দিয়েছেন এবং প্রসাদ গ্রহণ করেছেন। আপনাদের সকলের উপস্থিতি আমাদের মুগ্ধ করেছে। মা মনসা সকলের মঙ্গল করুন।</p><p><br></p><p>এ অনুষ্ঠানে আমন্ত্রিত অতিথিবৃন্দ, এলাকার ও দূর-দূরান্ত থেকে আগত গণ্যমান্য ব্যক্তিবর্গ, আমাদের মাননীয় উপদেষ্টামণ্ডলী, কার্যনির্বাহী কমিটির সভাপতি ও সম্পাদকসহ সকল সদস্য এবং স্বেচ্ছাসেবকবৃন্দ উপস্থিত ছিলেন।</p><p>আমাদের বাৎসরিক পূজা সফলভাবে সম্পন্ন করার পেছনে অবদান রাখা সকলকে জানাই আন্তরিক ধন্যবাদ।</p><p>সকলের জন্য মঙ্গল কামনা করছি। মা মনসার কৃপা সকলের ওপর বর্ষিত হোক।</p>', 'https://scontent.fdac5-2.fna.fbcdn.net/v/t39.30808-6/778767484_122174848412732108_4920150115462412158_n.jpg?stp=dst-jpg_tt6&cstp=mx1066x1600&ctp=s1066x1600&_nc_cat=107&ccb=1-7&_nc_sid=833d8c&_nc_ohc=ac_dmfb7mmcQ7kNvwH85NV8&_nc_oc=AdqIpyz_Iug5Z_yJPznelx8nAMjcJpMnIvJDMnHjqMpUOWMZaHBjpIbAv1m03B06bwI&_nc_zt=23&_nc_ht=scontent.fdac5-2.fna&_nc_gid=thRToz37PVuSb4MoTSUgAg&_nc_ss=7b2a8&oh=00_AQEaCI_qORLNmc4Nt0O1iUHzjQitoYI5x0LtbJqM8fG1Nw&oe=6A8BC027') ON CONFLICT (id) DO NOTHING;
