INSERT INTO public.notices (id, date, title, text) VALUES (5, '2026-08-19', 'গৈলার ঐতিহ্যবাহী শ্রীশ্রী মা মনসা মন্দিরের বাৎসরিক পূজা সফলভাবে উদযাপিত হয়েছে।', '<p>কবি বিজয় গুপ্তের স্মৃতি রক্ষা ও মা মনসা মন্দির সংরক্ষণ ও উন্নয়ন কমিটি-এর উদ্যোগে আয়োজিত এই পবিত্র উৎসবে বিগত বছরগুলোর তুলনায় এ বছর <strong>রেকর্ড সংখ্যক সর্বোচ্চ ভক্তের সমাগম ঘটেছে</strong>। মন্দির প্রাঙ্গণ ছিল কানায় কানায় পূর্ণ। </p><p><br></p><p>ডিজিটাল প্লাটফর্ম গুলোতেও ব্যাপক প্রচার প্রচারণা হয়েছে। অসংখ্য গণমাধ্যমে খবর হয়েছে। হাজার হাজার ভক্ত মায়ের চরণে পূজা দিয়েছেন এবং প্রসাদ গ্রহণ করেছেন। আপনাদের সকলের উপস্থিতি আমাদের মুগ্ধ করেছে। মা মনসা সকলের মঙ্গল করুন।</p><p><br></p><p>এ অনুষ্ঠানে আমন্ত্রিত অতিথিবৃন্দ, এলাকার ও দূর-দূরান্ত থেকে আগত গণ্যমান্য ব্যক্তিবর্গ, আমাদের মাননীয় উপদেষ্টামণ্ডলী, কার্যনির্বাহী কমিটির সভাপতি ও সম্পাদকসহ সকল সদস্য এবং স্বেচ্ছাসেবকবৃন্দ উপস্থিত ছিলেন।</p><p>আমাদের বাৎসরিক পূজা সফলভাবে সম্পন্ন করার পেছনে অবদান রাখা সকলকে জানাই আন্তরিক ধন্যবাদ।</p><p>সকলের জন্য মঙ্গল কামনা করছি। মা মনসার কৃপা সকলের ওপর বর্ষিত হোক।</p><p><br></p><p>আপনাদের অনুদান এই মহৎ ও পবিত্র কাজ সফল করতে অত্যন্ত গুরুত্বপূর্ণ। মন্দির সংরক্ষণ ও উন্নয়নের জন্য আপনাদের সহায়তার হাত বাড়িয়ে দিন।</p><p>বিকাশ (bKash)-এর মাধ্যমে অনুদান পাঠাতে নিচের পার্সোনাল অ্যাকাউন্টে সেন্ড মানি (Send Money) করুন:</p><p>বিকাশ নম্বর: 01722428334</p><p><br></p><p>মন্দির উন্নয়নে অংশ নিতে আগ্রহীদের আমাদের নির্বাহী কমিটির সঙ্গে যোগাযোগ করার জন্য বিনীত অনুরোধ করা হলো।</p><p>যোগাযোগ:</p><p>সভাপতি: </p><p>ড. বিনয় ভূষণ রায় (01717503657)</p><p>অর্থ সম্পাদক: </p><p>শ্রী সন্তোষ কর্মকার (01727075254)</p><p>সহ-অর্থ সম্পাদক: </p><p>শ্রী গৌতম চন্দ্র সরকার (01741771547)</p><p>সার্বিক তত্ত্বাবধানে:</p><p>কবি বিজয় গুপ্তের স্মৃতি রক্ষা এবং শ্রীশ্রী মা মনসা মন্দির সংরক্ষণ ও উন্নয়ন কমিটি।</p><p>গৈলা, আগৈলঝাড়া, বরিশাল<img src="https://static.xx.fbcdn.net/images/emoji.php/v9/t4b/2/16/1f4cc.png" alt="📌" height="16" width="16"> মন্দির সম্পর্কিত সকল আপডেট ও নোটিশ পেতে:</p><p>আমাদের ফেসবুক পেজটি ফলো করুন এবং আমাদের ওয়েবসাইট ভিজিট করুন:</p><p>ওয়েবসাইট: manasamondirgoila.com</p><p><br></p>') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.notices (id, date, title, text) VALUES (1, '2025-11-18', 'প্রতি রবিবার সাপ্তাহিক খিচুড়ি প্রসাদ বিতরণ ', 'শ্রী শ্রী মা মনসা মন্দিরে প্রতি রবিবার সাপ্তাহিক খিচুড়ি প্রসাদ বিতরণ করা হচ্ছে সবাইকে খিচুড়ি প্রসাদ গ্রহণ করার জন্য আমন্ত্রিত। প্রসাদ বিতরণে অনুদান অথবা সহযোগিতা করতে আগ্রহীরা আমাদের নির্বাহী কমিটির সঙ্গে যোগাযোগ করতে অনুরোধ করা হলো।
মা মনসার কৃপা সকলের ওপর বর্ষিত হোক।

আদেশক্রমে: কবি বিজয় গুপ্তের স্মৃতি রক্ষা, শ্রী শ্রী মা মনসা মন্দির সংরক্ষণ ও উন্নয়ন কমিটি।') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.notices (id, date, title, text) VALUES (2, '2026-03-22', 'কার্যকারী কমিটির জরুরি মিটিং ও সাপ্তাহিক প্রসাদ বিতরণ', 'কার্যকারী কমিটির সকল সদস্যবৃন্দের অবগতির জন্য জানানো যাচ্ছে যে, আগামী ২২/০৩/২০২৬ তারিখ সকাল ১০ টার সময়ে একটি জরুরি মিটিং অনুষ্ঠিত হবে।

উক্ত মিটিং শেষে নিয়মিত সাপ্তাহিক প্রসাদ বিতরণ অনুষ্ঠিত হবে।

অতএব, সংশ্লিষ্ট সকলকে যথাসময়ে উপস্থিত থাকার জন্য বিশেষভাবে অনুরোধ করা হলো।
মা মনসার অশেষ কৃপা সকলের ওপর বর্ষিত হোক।

📍 স্থান: শ্রী শ্রী মা মনসা মন্দির প্রাঙ্গন  
🕒 সময়: সকাল ১০ টা
📅 তারিখ: ২২/০৩/২০২৬

অনুরোধক্রমে,
কবি বিজয় গুপ্তের স্মৃতি রক্ষা, শ্রী শ্রী মা মনসা মন্দির সংরক্ষণ ও উন্নয়ন কমিটি।') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.notices (id, date, title, text) VALUES (3, '2026-04-14', 'বাংলা নববর্ষ ১৪৩৩ উপলক্ষে প্রথমবারের মতো অনুষ্ঠিত হচ্ছে কবি বিজয় গুপ্ত মেলা', 'বর্ষবরণের আনন্দে চলে আসুন "কবি বিজয় গুপ্ত মেলায়"! 

বাংলা নববর্ষ ১৪৩৩ ও পহেলা বৈশাখ উপলক্ষে আগামী ১৪ই এপ্রিল গৈলা শ্রীশ্রী মা-মনসা মন্দির প্রাঙ্গণে প্রথমবারের মতো অনুষ্ঠিত হতে যাচ্ছে দিনব্যাপী মেলা ও মনোজ্ঞ সাংস্কৃতিক অনুষ্ঠান।
এই আয়োজনে আপনি সপরিবারে সাদরে আমন্ত্রিত। আসুন, একসাথে উদ্‌যাপন করি বাঙালির প্রাণের উৎসব! ✨

তারিখ: ১লা বৈশাখ, ১৪৩৩ বঙ্গাব্দ ( ১৪ এপ্রিল, ২০২৬)
স্থান: মা মনসা মন্দির প্রাঙ্গনে, গৈলা
মেলা: সকাল ৮টা থেকে রাত ৮টা
সাংস্কৃতিক অনুষ্ঠান: বিকাল ৩টা থেকে রাত ৮টা 

মা মনসা সকলের মঙ্গল করুন। “জয় মা-মনসা” 

আয়োজন ও সার্বিক তত্ত্বাবধানে:
কবি বিজয় গুপ্তের স্মৃতিরক্ষা, শ্রীশ্রী মা-মনসা মন্দির সংরক্ষণ ও উন্নয়ন কমিটি।
গৈলা, আগৈলঝাড়া, বরিশাল।

📌 মন্দির সম্পর্কিত সকল আপডেট ও নোটিশ পেতে:
আমাদের ফেসবুক পেজটি ফলো করুন এবং ভিজিট করুন আমাদের ওয়েবসাইট:
🌐 https://manasamondirgoila.vercel.app/') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.notices (id, date, title, text) VALUES (4, '2026-08-01', 'গৈলার ঐতিহ্যবাহী শ্রীশ্রী মা-মনসা মন্দিরের বাৎসরিক পূজা ও উৎসব-২০২৬ ', '<p>মধ্যযুগের প্রখ্যাত কবি বিজয় গুপ্ত প্রতিষ্ঠিত গৈলার ঐতিহ্যবাহী শ্রীশ্রী মা-মনসা মন্দিরের বাৎসরিক পূজা ও উৎসব-২০২৬ অনুষ্ঠিত হতে যাচ্ছে। কবি বিজয় গুপ্তের স্মৃতি রক্ষা ও মা-মনসা মন্দির সংরক্ষণ ও উন্নয়ন কমিটি’-এর উদ্যোগে আয়োজিত এই পবিত্র উৎসবে আপনাদের সকলকে সবান্ধবে আমন্ত্রণ জানাচ্ছি।</p><p><br></p><p><strong>বিস্তারিত সময়সূচী:</strong></p><p><br></p><ul><li>রায়ানি গান: ১৩, ১৪, ১৫ আগস্ট ২০২৬ (রোজ বৃহস্পতি, শুক্র, শনিবার) ২৭, ২৮ ও ২৯ শ্রাবণ ১৪৩৩ বঙ্গাব্দ।</li><li>মূল পূজা: ১৮ আগস্ট ২০২৬ (রোজ মঙ্গলবার) ৩২ শ্রাবণ ১৪৩৩ বঙ্গাব্দ।</li><li>স্থান: মনসা মন্দির প্রাঙ্গন, গৈলা, আগৈলঝাড়া, বরিশাল।</li></ul><p><br></p><p>আপনাদের অনুদান এই মহৎ ও পবিত্র কাজ সফল করতে অত্যন্ত গুরুত্বপূর্ণ। মন্দির সংরক্ষণ ও উন্নয়নের জন্য আপনার সহায়তার হাত বাড়িয়ে দিন।</p><p>bKash-এর মাধ্যমে অনুদান পাঠাতে (পার্সোনাল একাউন্ট&nbsp;- সেন্ড মানি করুন)</p><p><br></p><p><strong>bKash নম্বর: 01722428334 (Send Money)</strong></p><p><br></p><p>সার্বিক তত্ত্বাবধানে: কবি বিজয় গুপ্তের স্মৃতি রক্ষা, শ্রী শ্রী মা মনসা মন্দির সংরক্ষণ ও উন্নয়ন কমিটি। গৈলা, আগৈলঝাড়া, বরিশাল।</p><p><br></p><p>📌 মন্দির সম্পর্কিত সকল আপডেট ও নোটিশ পেতে: আমাদের ফেসবুক পেজটি ফলো করুন এবং ভিজিট করুন আমাদের ওয়েবসাইট: <a href="https://www.manasamondirgoila.com" target="_blank">manasamondirgoila.com</a></p><p><br></p><p><br></p>') ON CONFLICT (id) DO NOTHING;
